 static void Baseline(){rows=new List<string>();var args=Environment.GetCommandLineArgs();report=args[Array.IndexOf(args,"-frontReport")+1];var actors=UnityEngine.Object.FindObjectsByType<TrainingFighter>(FindObjectsSortMode.None);var images=UnityEngine.Object.FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponentInParent<TrainingStage>()==null).ToArray();Check(actors.Length==2,"historical Scene has two actual Fighter bodies");Check(images.Length==3,"historical Scene reproduces three visible character sprites");var cpu=Hud().dummy.Fighter;var duplicate=images.Where(r=>r.GetComponentInParent<TrainingFighter>()==cpu).ToArray();Check(duplicate.Length==2,"historical CPU owns two visible sprites");Check(duplicate.Count(r=>r==cpu.GetComponent<ArmoredStaticPoseView>().image)==1,"only one of the two CPU sprites is driven by presentation");CaptureHud("baseline-duplicate");Finish(0);}
