 static Button Button(string name)=>menu.GetComponentsInChildren<Button>().Single(b=>b.name==name);
 static Button TitleButton()=>UnityEngine.Object.FindObjectsByType<Button>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(b=>b.name=="NavTitle");
 static void Actors(string context){var actors=UnityEngine.Object.FindObjectsByType<TrainingFighter>(FindObjectsSortMode.None);Check(actors.Length==2,context+": exactly two fighters");var images=UnityEngine.Object.FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponentInParent<TrainingStage>()==null).ToArray();rows.Add(context+": character renderers "+string.Join(", ",images.Select(r=>r.name+" owner="+r.GetComponentInParent<TrainingFighter>()?.name)));Check(images.Length==2,context+": exactly two enabled character sprite renderers (stage floor excluded)");foreach(var f in actors){var v=f.GetComponent<ArmoredStaticPoseView>();var owned=images.Where(r=>r.GetComponentInParent<TrainingFighter>()==f).ToArray();Check(owned.Length==1&&owned[0]==v.image,context+": single controlled sprite for "+f.name);Check(f.GetComponent<TrainingMotor2D>()!=null&&f.GetComponentsInChildren<Collider2D>().Any(c=>c.enabled),context+": physical body remains on "+f.name);Check(v.characterProfile.characterId=="awari",context+": confirmed character on "+f.name);}}
 static void Capture(string name)=>CaptureCamera(menu.MenuCamera,name);
 static void CaptureHud(string name)=>CaptureCamera(Hud().HudCamera,name);
 static void CaptureCamera(Camera camera,string name){var previous=camera.targetTexture;var active=RenderTexture.active;var target=new RenderTexture(1280,720,24);target.Create();try{camera.targetTexture=target;if(menu!=null&&camera==menu.MenuCamera)menu.RefreshLayout(1280,720);var overlay=Hud();if(overlay!=null&&camera==overlay.HudCamera){overlay.LayoutHud(1280,720);overlay.RefreshMotionLayout(1280,720);if(Camera.main!=null&&Camera.main.targetTexture!=null)Camera.main.Render();}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Path.ChangeExtension(report,null)+"-"+name+".png",image.EncodeToPNG());UnityEngine.Object.Destroy(image);}finally{camera.targetTexture=previous;RenderTexture.active=active;target.Release();UnityEngine.Object.Destroy(target);}}
 static void Tick(){try{if(!EditorApplication.isPlaying||Time.frameCount<3)return;if(rows==null){if(SessionState.GetBool("ShiokaFrontBaseline",false)){if(Time.frameCount>=8)Baseline();return;}Setup();return;}InputSystem.Update();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Front flow timeout "+current?.name);if(current!=null){if(Time.frameCount-frame<current.frames)return;current.check?.Invoke();current=null;}if(steps.Count==0){Finish(0);return;}current=steps.Dequeue();current.before?.Invoke();InputSystem.QueueStateEvent(pad,current.padState);Keys(current.keys);frame=Time.frameCount;}catch(Exception e){rows?.Add("EXCEPTION "+e);Debug.LogException(e);Finish(1);}}
 static void Finish(int exit){SessionState.SetBool(Pending,false);SessionState.SetBool("ShiokaFrontBaseline",false);EditorApplication.update-=Tick;SceneManager.sceneLoaded-=SceneLoaded;if(keyboard!=null){Keys();InputSystem.RemoveDevice(keyboard);}if(pad!=null)InputSystem.RemoveDevice(pad);keyProfile?.Dispose();if(old!=null)InputSystem.settings=old;if(temporary!=null)UnityEngine.Object.DestroyImmediate(temporary);Time.timeScale=1;if(rows!=null){rows.Add(count+" PASS; exit="+exit+"; virtual keyboard and Button.onClick, not physical devices/mouse");rows.Add("Isolated recovery "+folder);File.WriteAllLines(report,rows);}EditorApplication.Exit(exit);}
